def reach(win,D,src=1006,tgt=1860):
    actt={}
    for u,v,t in win:
        if u==src: actt.setdefault(v,t)
        elif u in actt and 0<=t-actt[u]<=D: actt.setdefault(v,t)
    return (tgt in actt), len(actt)
